SELECT pi.id AS patient_id,
  pi.in_hospital_no AS in_hospital_no,
  pi.name AS patient_name,
  pi.gender AS gender,
  pi.bed_code AS bed_code,
  pi.age AS age,
  pi.depart_code AS depart_code,
  pi.ward_name AS ward_name,
  pi.out_vest_type AS out_vest_type,
  pi.charge_doctor_name AS charge_doctor_name,
  pi.in_depart_time AS in_depart_time,
  pi.out_depart_time AS out_depart_time,
  pi.out_hospital_time AS out_hospital_time,
  CAST(pi.diagnosis_content AS VARCHAR(2000)) AS diagnosis_content,
  CASE WHEN EXISTS (SELECT 1 FROM "zing_icu_db_prod"."patient_info_diagnosis" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE '%深静脉血栓%' OR d.diag_name LIKE '%下肢静脉血栓%' OR d.diag_name LIKE '%肺栓塞%')) THEN 1 ELSE 0 END AS dvt_diag,
  CASE WHEN pi.out_vest_type = 3 AND EXISTS (SELECT 1 FROM "zing_icu_db_prod"."patient_info_diagnosis" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE '%深静脉血栓%' OR d.diag_name LIKE '%下肢静脉血栓%' OR d.diag_name LIKE '%肺栓塞%')) THEN 1 ELSE 0 END AS dvt_death,
  CASE WHEN pi.out_vest_type = 3 AND pi.out_depart_time >= TIMESTAMP '2026-09-01 00:00:00' AND pi.out_depart_time < TIMESTAMP '2026-10-01 00:00:00' THEN 1 ELSE 0 END AS died_in_period,
  CASE WHEN pi.out_depart_time >= TIMESTAMP '2026-09-01 00:00:00' AND pi.out_depart_time < TIMESTAMP '2026-10-01 00:00:00' THEN 1 ELSE 0 END AS out_in_period,
  CASE WHEN EXISTS (SELECT 1 FROM "zing_icu_db_prod"."patient_advice_execute_drug" e JOIN "zing_icu_db_prod"."patient_advice_execute" x ON x.id = e.execute_id WHERE e.patient_id = pi.id AND e.del_flag = 0 AND x.del_flag = 0 AND x.start_time < TIMESTAMP '2026-10-01 00:00:00' AND (x.end_time IS NULL OR x.end_time >= TIMESTAMP '2026-09-01 00:00:00') AND (e.drug_name LIKE '%肝素%' OR e.drug_name LIKE '%利伐沙班%' OR e.drug_name LIKE '%达比加群酯%' OR e.drug_name LIKE '%阿哌沙班%' OR e.drug_name LIKE '%磺达肝癸%')) THEN 1 ELSE 0 END AS dvt_drug_status,
  CASE WHEN EXISTS (SELECT 1 FROM "zing_icu_db_prod"."patient_advice_original" o WHERE o.in_hospital_serial_no = pi.in_hospital_serial_no AND o.start_time < TIMESTAMP '2026-10-01 00:00:00' AND (o.end_time IS NULL OR o.end_time >= TIMESTAMP '2026-09-01 00:00:00') AND (o.advice_name LIKE '%气压治疗%' OR o.advice_name LIKE '%肢体加压%' OR o.advice_name LIKE '%间歇充气%' OR o.advice_name LIKE '%加压泵%' OR o.advice_name LIKE '%空气波%' OR o.advice_name LIKE '%梯度压力%' OR o.advice_name LIKE '%抗血栓%' OR o.advice_name LIKE '%弹力袜%')) THEN 1 ELSE 0 END AS dvt_mech_status,
  CASE WHEN EXISTS (SELECT 1 FROM "zing_icu_db_prod"."patient_advice_original" o WHERE o.in_hospital_serial_no = pi.in_hospital_serial_no AND o.start_time < TIMESTAMP '2026-10-01 00:00:00' AND (o.end_time IS NULL OR o.end_time >= TIMESTAMP '2026-09-01 00:00:00') AND (o.advice_name LIKE '%下腔静脉滤器%' OR o.advice_name LIKE '%滤器置入%')) THEN 1 ELSE 0 END AS dvt_filter_status,
  CASE WHEN EXISTS (SELECT 1 FROM "zing_icu_db_prod"."patient_advice_execute_drug" e JOIN "zing_icu_db_prod"."patient_advice_execute" x ON x.id = e.execute_id WHERE e.patient_id = pi.id AND e.del_flag = 0 AND x.del_flag = 0 AND x.start_time < TIMESTAMP '2026-10-01 00:00:00' AND (x.end_time IS NULL OR x.end_time >= TIMESTAMP '2026-09-01 00:00:00') AND (e.drug_name LIKE '%肝素%' OR e.drug_name LIKE '%利伐沙班%' OR e.drug_name LIKE '%达比加群酯%' OR e.drug_name LIKE '%阿哌沙班%' OR e.drug_name LIKE '%磺达肝癸%')) OR EXISTS (SELECT 1 FROM "zing_icu_db_prod"."patient_advice_original" o WHERE o.in_hospital_serial_no = pi.in_hospital_serial_no AND o.start_time < TIMESTAMP '2026-10-01 00:00:00' AND (o.end_time IS NULL OR o.end_time >= TIMESTAMP '2026-09-01 00:00:00') AND (o.advice_name LIKE '%气压治疗%' OR o.advice_name LIKE '%肢体加压%' OR o.advice_name LIKE '%间歇充气%' OR o.advice_name LIKE '%加压泵%' OR o.advice_name LIKE '%空气波%' OR o.advice_name LIKE '%梯度压力%' OR o.advice_name LIKE '%抗血栓%' OR o.advice_name LIKE '%弹力袜%')) OR EXISTS (SELECT 1 FROM "zing_icu_db_prod"."patient_advice_original" o WHERE o.in_hospital_serial_no = pi.in_hospital_serial_no AND o.start_time < TIMESTAMP '2026-10-01 00:00:00' AND (o.end_time IS NULL OR o.end_time >= TIMESTAMP '2026-09-01 00:00:00') AND (o.advice_name LIKE '%下腔静脉滤器%' OR o.advice_name LIKE '%滤器置入%')) THEN 1 ELSE 0 END AS dvt_prevent_status,
  CASE WHEN EXISTS (SELECT 1 FROM "zing_icu_db_prod"."patient_advice_execute_drug" e JOIN "zing_icu_db_prod"."patient_advice_execute" x ON x.id = e.execute_id WHERE e.patient_id = pi.id AND e.del_flag = 0 AND x.del_flag = 0 AND x.start_time < TIMESTAMP '2026-10-01 00:00:00' AND (x.end_time IS NULL OR x.end_time >= TIMESTAMP '2026-09-01 00:00:00') AND (e.drug_name LIKE '%肝素%' OR e.drug_name LIKE '%利伐沙班%' OR e.drug_name LIKE '%达比加群酯%' OR e.drug_name LIKE '%阿哌沙班%' OR e.drug_name LIKE '%磺达肝癸%')) AND NOT EXISTS (SELECT 1 FROM "zing_icu_db_prod"."patient_advice_original" o WHERE o.in_hospital_serial_no = pi.in_hospital_serial_no AND o.start_time < TIMESTAMP '2026-10-01 00:00:00' AND (o.end_time IS NULL OR o.end_time >= TIMESTAMP '2026-09-01 00:00:00') AND (o.advice_name LIKE '%气压治疗%' OR o.advice_name LIKE '%肢体加压%' OR o.advice_name LIKE '%间歇充气%' OR o.advice_name LIKE '%加压泵%' OR o.advice_name LIKE '%空气波%' OR o.advice_name LIKE '%梯度压力%' OR o.advice_name LIKE '%抗血栓%' OR o.advice_name LIKE '%弹力袜%' OR o.advice_name LIKE '%下腔静脉滤器%' OR o.advice_name LIKE '%滤器置入%')) THEN 1 ELSE 0 END AS dvt_only_drug,
  CASE WHEN EXISTS (SELECT 1 FROM "zing_icu_db_prod"."patient_advice_original" o WHERE o.in_hospital_serial_no = pi.in_hospital_serial_no AND o.start_time < TIMESTAMP '2026-10-01 00:00:00' AND (o.end_time IS NULL OR o.end_time >= TIMESTAMP '2026-09-01 00:00:00') AND (o.advice_name LIKE '%气压治疗%' OR o.advice_name LIKE '%肢体加压%' OR o.advice_name LIKE '%间歇充气%' OR o.advice_name LIKE '%加压泵%' OR o.advice_name LIKE '%空气波%' OR o.advice_name LIKE '%梯度压力%' OR o.advice_name LIKE '%抗血栓%' OR o.advice_name LIKE '%弹力袜%')) AND NOT EXISTS (SELECT 1 FROM "zing_icu_db_prod"."patient_advice_execute_drug" e JOIN "zing_icu_db_prod"."patient_advice_execute" x ON x.id = e.execute_id WHERE e.patient_id = pi.id AND e.del_flag = 0 AND x.del_flag = 0 AND x.start_time < TIMESTAMP '2026-10-01 00:00:00' AND (x.end_time IS NULL OR x.end_time >= TIMESTAMP '2026-09-01 00:00:00') AND (e.drug_name LIKE '%肝素%' OR e.drug_name LIKE '%利伐沙班%' OR e.drug_name LIKE '%达比加群酯%' OR e.drug_name LIKE '%阿哌沙班%' OR e.drug_name LIKE '%磺达肝癸%')) AND NOT EXISTS (SELECT 1 FROM "zing_icu_db_prod"."patient_advice_original" o2 WHERE o2.in_hospital_serial_no = pi.in_hospital_serial_no AND (o2.advice_name LIKE '%下腔静脉滤器%' OR o2.advice_name LIKE '%滤器置入%')) THEN 1 ELSE 0 END AS dvt_only_mech,
  CASE WHEN EXISTS (SELECT 1 FROM "zing_icu_db_prod"."patient_advice_original" o WHERE o.in_hospital_serial_no = pi.in_hospital_serial_no AND o.start_time < TIMESTAMP '2026-10-01 00:00:00' AND (o.end_time IS NULL OR o.end_time >= TIMESTAMP '2026-09-01 00:00:00') AND (o.advice_name LIKE '%下腔静脉滤器%' OR o.advice_name LIKE '%滤器置入%')) AND NOT EXISTS (SELECT 1 FROM "zing_icu_db_prod"."patient_advice_execute_drug" e JOIN "zing_icu_db_prod"."patient_advice_execute" x ON x.id = e.execute_id WHERE e.patient_id = pi.id AND e.del_flag = 0 AND x.del_flag = 0 AND x.start_time < TIMESTAMP '2026-10-01 00:00:00' AND (x.end_time IS NULL OR x.end_time >= TIMESTAMP '2026-09-01 00:00:00') AND (e.drug_name LIKE '%肝素%' OR e.drug_name LIKE '%利伐沙班%' OR e.drug_name LIKE '%达比加群酯%' OR e.drug_name LIKE '%阿哌沙班%' OR e.drug_name LIKE '%磺达肝癸%')) AND NOT EXISTS (SELECT 1 FROM "zing_icu_db_prod"."patient_advice_original" o2 WHERE o2.in_hospital_serial_no = pi.in_hospital_serial_no AND (o2.advice_name LIKE '%气压治疗%' OR o2.advice_name LIKE '%肢体加压%' OR o2.advice_name LIKE '%间歇充气%' OR o2.advice_name LIKE '%加压泵%' OR o2.advice_name LIKE '%空气波%' OR o2.advice_name LIKE '%梯度压力%' OR o2.advice_name LIKE '%抗血栓%' OR o2.advice_name LIKE '%弹力袜%')) THEN 1 ELSE 0 END AS dvt_only_filter
FROM "zing_icu_db_prod"."patient_info" pi
WHERE (pi.del_flag = 0) AND (pi.in_depart_time IS NOT NULL) AND (pi.in_depart_time < TIMESTAMP '2026-10-01 00:00:00') AND ((pi.out_depart_time IS NULL OR pi.out_depart_time >= TIMESTAMP '2026-09-01 00:00:00'))